content:
/* Reset & Base Variables */
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --primary-light: #eef2ff;
  --secondary-color: #06b6d4;
  --success-color: #10b981;
  --success-light: #ecfdf5;
  --warning-color: #f59e0b;
  --danger-color: #ef4444;
  --danger-light: #fef2f2;
  --bg-gradient: linear-gradient(135deg, #0f172a 0%, #1e1b4b 50%, #312e81 100%);
  --card-front-bg: linear-gradient(145deg, #ffffff 0%, #f8fafc 100%);
  --card-back-bg: linear-gradient(145deg, #f0fdf4 0%, #e0f2fe 100%);
  --text-main: #0f172a;
  --text-muted: #64748b;
  --text-light: #f8fafc;
  --border-color: #e2e8f0;
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 22px;
  --radius-full: 9999px;
  --shadow-sm: 0 2px 4px rgba(0, 0, 0, 0.06);
  --shadow-md: 0 8px 20px rgba(0, 0, 0, 0.12);
  --shadow-lg: 0 16px 36px rgba(0, 0, 0, 0.25);
  --shadow-card: 0 20px 40px -15px rgba(0, 0, 0, 0.35);
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background: var(--bg-gradient);
  color: var(--text-light);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

/* App Layout */
.app-container {
  width: 100%;
  max-width: 640px;
  min-height: 100vh;
  margin: 0 auto;
  padding: 24px 16px 40px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* Header */
.app-header {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.header-title {
  font-size: 1.85rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  background: linear-gradient(135deg, #a5b4fc, #ffffff, #67e8f9);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.header-subtitle {
  font-size: 0.88rem;
  color: #94a3b8;
  font-weight: 500;
}

/* Stats & Progress */
.stats-bar {
  background: rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: var(--radius-md);
  padding: 12px 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.stats-text {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.85rem;
  font-weight: 600;
  color: #cbd5e1;
}

.progress-track {
  width: 100%;
  height: 8px;
  background: rgba(0, 0, 0, 0.3);
  border-radius: var(--radius-full);
  overflow: hidden;
  position: relative;
}

.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, #10b981, #06b6d4);
  border-radius: var(--radius-full);
  transition: width 0.4s ease-out;
}

/* Filter Chips */
.filter-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
  padding: 2px 0;
}

.chip-btn {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: #cbd5e1;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  user-select: none;
}

.chip-btn:hover {
  background: rgba(255, 255, 255, 0.18);
  color: #ffffff;
  transform: translateY(-1px);
}

.chip-btn-active {
  background: #4f46e5;
  color: #ffffff;
  border-color: #818cf8;
  box-shadow: 0 0 12px rgba(99, 102, 241, 0.45);
}

/* 3D Flip Card System */
.card-wrapper {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  margin: 6px 0;
}

.card-perspective {
  perspective: 1200px;
  width: 100%;
  height: 380px;
  cursor: pointer;
}

.flashcard {
  width: 100%;
  height: 100%;
  position: relative;
}

.flashcard-inner {
  width: 100%;
  height: 100%;
  position: relative;
  transform-style: preserve-3d;
  transition: transform 0.65s cubic-bezier(0.34, 1.3, 0.64, 1);
  border-radius: var(--radius-lg);
}

.flashcard-inner.is-flipped {
  transform: rotateY(180deg);
}

.flashcard-front,
.flashcard-back {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  border-radius: var(--radius-lg);
  padding: 26px 24px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-shadow: var(--shadow-card);
  user-select: none;
}

/* Front Face */
.flashcard-front {
  background: var(--card-front-bg);
  color: var(--text-main);
  border: 2px solid rgba(255, 255, 255, 0.8);
}

/* Back Face */
.flashcard-back {
  background: var(--card-back-bg);
  color: var(--text-main);
  transform: rotateY(180deg);
  border: 2px solid #86efac;
}

/* Card Header & Badges */
.card-badge-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
}

.badge-category {
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 4px 10px;
  border-radius: var(--radius-full);
  background: #e0e7ff;
  color: #3730a3;
}

.badge-pos {
  font-size: 0.72rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: var(--radius-full);
  background: #f1f5f9;
  color: #475569;
}

/* Card Main Typography */
.word-main {
  font-size: 2.3rem;
  font-weight: 800;
  color: #0f172a;
  text-align: center;
  letter-spacing: -0.02em;
  margin-top: 10px;
  word-break: break-word;
}

.phonetic-text {
  font-size: 1.05rem;
  color: #64748b;
  font-family: 'Lucida Sans Unicode', 'Arial Unicode MS', sans-serif;
  text-align: center;
  margin-top: 4px;
}

/* Sound Button */
.sound-btn {
  background: #eef2ff;
  color: var(--primary-color);
  border: 1px solid #c7d2fe;
  border-radius: var(--radius-full);
  padding: 8px 16px;
  font-size: 0.88rem;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  cursor: pointer;
  margin: 12px auto 0;
  transition: all 0.2s ease;
}

.sound-btn:hover {
  background: #e0e7ff;
  transform: scale(1.05);
  box-shadow: 0 4px 10px rgba(99, 102, 241, 0.2);
}

.sound-btn:active {
  transform: scale(0.97);
}

/* Card Bottom Helpers */
.flip-hint {
  font-size: 0.78rem;
  color: #94a3b8;
  text-align: center;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
}

/* Back Face Content */
.meaning-main {
  font-size: 1.8rem;
  font-weight: 800;
  color: #065f46;
  text-align: center;
  letter-spacing: -0.01em;
  margin: 12px 0 16px;
  word-break: break-word;
}

.example-box {
  background: rgba(255, 255, 255, 0.75);
  backdrop-filter: blur(6px);
  border: 1px solid #d1fae5;
  border-radius: var(--radius-md);
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.example-en {
  font-size: 0.95rem;
  font-weight: 600;
  color: #1e293b;
  line-height: 1.45;
}

.example-ja {
  font-size: 0.85rem;
  color: #475569;
  line-height: 1.4;
}

/* Master Button */
.master-btn {
  background: #f8fafc;
  border: 1px solid #cbd5e1;
  color: #475569;
  padding: 8px 16px;
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  transition: all 0.2s ease;
  margin: 0 auto;
}

.master-btn:hover {
  background: #f1f5f9;
  border-color: #94a3b8;
}

.master-btn-active {
  background: #10b981;
  border-color: #059669;
  color: #ffffff;
  box-shadow: 0 4px 12px rgba(16, 185, 129, 0.35);
}

.master-btn-active:hover {
  background: #059669;
}

/* Primary Controls Row */
.controls-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
}

.nav-btn {
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: #ffffff;
  padding: 10px 18px;
  border-radius: var(--radius-md);
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 44px;
  transition: all 0.2s ease;
  user-select: none;
}

.nav-btn:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.2);
  transform: translateY(-2px);
}

.nav-btn:active:not(:disabled) {
  transform: translateY(0);
}

.nav-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.nav-btn-primary {
  background: #4f46e5;
  border-color: #6366f1;
  box-shadow: 0 4px 14px rgba(79, 70, 229, 0.4);
}

.nav-btn-primary:hover:not(:disabled) {
  background: #4338ca;
}

/* Secondary Action Bar */
.action-bar {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  flex-wrap: wrap;
  width: 100%;
}

.sub-btn {
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: #cbd5e1;
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.sub-btn:hover {
  background: rgba(255, 255, 255, 0.15);
  color: #ffffff;
}

/* Modal System */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.75);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  animation: fadeIn 0.2s ease-out forwards;
}

.modal-content {
  background: #ffffff;
  color: var(--text-main);
  width: 100%;
  max-width: 580px;
  max-height: 85vh;
  border-radius: var(--radius-lg);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  box-shadow: var(--shadow-lg);
  animation: slideUp 0.25s ease-out forwards;
}

.modal-header {
  padding: 18px 24px;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.modal-header h2 {
  font-size: 1.25rem;
  font-weight: 700;
  color: #0f172a;
}

.modal-body {
  padding: 20px 24px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* Form Styles within Modal */
.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.form-label {
  font-size: 0.82rem;
  font-weight: 700;
  color: #334155;
}

.form-input,
.form-select {
  width: 100%;
  padding: 9px 12px;
  border: 1.5px solid var(--border-color);
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  color: #0f172a;
  background-color: #f8fafc;
  outline: none;
  transition: all 0.2s ease;
  font-family: inherit;
}

.form-input:focus,
.form-select:focus {
  border-color: var(--primary-color);
  background-color: #ffffff;
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.15);
}

.form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 8px;
}

/* Word Management Table */
.word-table {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 8px;
  border-top: 1px solid var(--border-color);
  padding-top: 16px;
}

.table-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  background: #f8fafc;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  transition: background 0.15s ease;
}

.table-row:hover {
  background: #f1f5f9;
}

.delete-btn {
  background: transparent;
  border: none;
  color: var(--danger-color);
  cursor: pointer;
  padding: 6px;
  border-radius: var(--radius-sm);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s ease;
}

.delete-btn:hover {
  background: var(--danger-light);
}

/* Keyframes */
@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes slideUp {
  from {
    opacity: 0;
    transform: translateY(20px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* Mobile & Touch Adjustments */
@media (max-width: 480px) {
  .app-container {
    padding: 16px 12px 30px;
    gap: 16px;
  }

  .header-title {
    font-size: 1.5rem;
  }

  .card-perspective {
    height: 350px;
  }

  .word-main {
    font-size: 2rem;
  }

  .meaning-main {
    font-size: 1.5rem;
  }

  .flashcard-front,
  .flashcard-back {
    padding: 20px 18px;
  }

  .example-en {
    font-size: 0.88rem;
  }

  .example-ja {
    font-size: 0.8rem;
  }

  .nav-btn {
    padding: 8px 12px;
    font-size: 0.85rem;
  }
}

export type CategoryType = '日常' | 'ビジネス' | 'TOEIC' | '旅行';

export type FilterCategory = 'すべて' | '日常' | 'ビジネス' | 'TOEIC' | '旅行';

export interface WordCard {
  id: string;
  english: string;
  japanese: string;
  phonetic: string;
  partOfSpeech: string;
  exampleSentence: string;
  exampleTranslation: string;
  category: CategoryType;
  isMastered: boolean;
}

export interface CardViewProps {
  card: WordCard;
  isFlipped: boolean;
  onFlip: () => void;
  onToggleMastered: (id: string) => void;
  onSpeak: (text: string) => void;
}

export interface WordListModalProps {
  isOpen: boolean;
  onClose: () => void;
  cards: WordCard[];
  onAddCard: (card: Omit<WordCard, 'id' | 'isMastered'>) => void;
  onDeleteCard: (id: string) => void;
}

import { FC, MouseEvent } from 'react';
import { Volume2, CheckCircle2, RotateCw } from 'lucide-react';
import { CardViewProps } from '../types';

const CardView: FC<CardViewProps> = ({
  card,
  isFlipped,
  onFlip,
  onToggleMastered,
  onSpeak,
}) => {
  const handleSoundClick = (e: MouseEvent<HTMLButtonElement>) => {
    e.stopPropagation();
    onSpeak?.(card.english);
  };

  const handleMasterClick = (e: MouseEvent<HTMLButtonElement>) => {
    e.stopPropagation();
    onToggleMastered?.(card.id);
  };

  return (
    <div className="card-wrapper">
      <div className="card-perspective" onClick={onFlip}>
        <div className="flashcard">
          <div className={`flashcard-inner ${isFlipped ? 'is-flipped' : ''}`}>
            {/* 表面 (Front Face) */}
            <div className="flashcard-front">
              <div className="card-badge-row">
                <span className="badge-category">{card.category}</span>
                <span className="badge-pos">{card.partOfSpeech}</span>
              </div>

              <div>
                <h1 className="word-main">{card.english}</h1>
                <p className="phonetic-text">{card.phonetic}</p>
                <button
                  type="button"
                  className="sound-btn"
                  onClick={handleSoundClick}
                  title="発音を聞く"
                >
                  <Volume2 size={16} />
                  <span>発音</span>
                </button>
              </div>

              <div className="flip-hint">
                <RotateCw size={14} />
                <span>タップで意味を表示</span>
              </div>
            </div>

            {/* 裏面 (Back Face) */}
            <div className="flashcard-back">
              <div className="card-badge-row">
                <span className="badge-category">{card.category}</span>
                <button
                  type="button"
                  className={`master-btn ${card.isMastered ? 'master-btn-active' : ''}`}
                  onClick={handleMasterClick}
                >
                  <CheckCircle2 size={16} />
                  <span>{card.isMastered ? '覚えた！' : '未暗記'}</span>
                </button>
              </div>

              <div>
                <h2 className="meaning-main">{card.japanese}</h2>
                <div className="example-box">
                  <p className="example-en">{card.exampleSentence}</p>
                  <p className="example-ja">{card.exampleTranslation}</p>
                </div>
              </div>

              <div className="flip-hint">
                <RotateCw size={14} />
                <span>タップで単語に戻る</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CardView;

import { FC, useState, FormEvent, MouseEvent } from 'react';
import { X, Trash2, Plus } from 'lucide-react';
import { WordListModalProps, CategoryType, WordCard } from '../types';

const categoryOptions: CategoryType[] = ['日常', 'ビジネス', 'TOEIC', '旅行'];

const WordListModal: FC<WordListModalProps> = ({
  isOpen,
  onClose,
  cards = [],
  onAddCard,
  onDeleteCard,
}) => {
  const [english, setEnglish] = useState('');
  const [japanese, setJapanese] = useState('');
  const [phonetic, setPhonetic] = useState('');
  const [partOfSpeech, setPartOfSpeech] = useState('名詞');
  const [category, setCategory] = useState<CategoryType>('日常');
  const [exampleSentence, setExampleSentence] = useState('');
  const [exampleTranslation, setExampleTranslation] = useState('');

  if (!isOpen) return null;

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!english.trim() || !japanese.trim()) return;

    onAddCard?.({
      english: english.trim(),
      japanese: japanese.trim(),
      phonetic: phonetic.trim() || `/${english.trim().toLowerCase()}/`,
      partOfSpeech: partOfSpeech.trim() || '名詞',
      category,
      exampleSentence: exampleSentence.trim() || 'No example sentence registered.',
      exampleTranslation: exampleTranslation.trim() || '例文は登録されていません。',
    });

    setEnglish('');
    setJapanese('');
    setPhonetic('');
    setPartOfSpeech('名詞');
    setCategory('日常');
    setExampleSentence('');
    setExampleTranslation('');
  };

  const handleOverlayClick = (e: MouseEvent<HTMLDivElement>) => {
    if (e.target === e.currentTarget) {
      onClose?.();
    }
  };

  return (
    <div className="modal-overlay" onClick={handleOverlayClick}>
      <div className="modal-content">
        <div className="modal-header">
          <h2>単語リスト管理 ({cards.length}語)</h2>
          <button type="button" className="sub-btn" onClick={onClose} aria-label="閉じる">
            <X size={18} />
          </button>
        </div>

        <div className="modal-body">
          {/* 単語追加フォーム */}
          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label className="form-label" htmlFor="word-en">英単語 *</label>
              <input
                id="word-en"
                type="text"
                className="form-input"
                placeholder="例: persistent"
                value={english}
                onChange={(e) => setEnglish(e.target.value)}
                required
              />
            </div>

            <div className="form-group" style={{ marginTop: '10px' }}>
              <label className="form-label" htmlFor="word-ja">日本語の意味 *</label>
              <input
                id="word-ja"
                type="text"
                className="form-input"
                placeholder="例: 粘り強い、持続する"
                value={japanese}
                onChange={(e) => setJapanese(e.target.value)}
                required
              />
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '10px', marginTop: '10px' }}>
              <div className="form-group">
                <label className="form-label" htmlFor="word-cat">カテゴリ</label>
                <select
                  id="word-cat"
                  className="form-select"
                  value={category}
                  onChange={(e) => setCategory(e.target.value as CategoryType)}
                >
                  {categoryOptions.map((cat) => (
                    <option key={cat} value={cat}>
                      {cat}
                    </option>
                  ))}
                </select>
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="word-pos">品詞</label>
                <input
                  id="word-pos"
                  type="text"
                  className="form-input"
                  placeholder="形容詞"
                  value={partOfSpeech}
                  onChange={(e) => setPartOfSpeech(e.target.value)}
                />
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="word-pho">発音記号</label>
                <input
                  id="word-pho"
                  type="text"
                  className="form-input"
                  placeholder="/pɚˈsɪs.tənt/"
                  value={phonetic}
                  onChange={(e) => setPhonetic(e.target.value)}
                />
              </div>
            </div>

            <div className="form-group" style={{ marginTop: '10px' }}>
              <label className="form-label" htmlFor="word-ex-en">例文 (英語)</label>
              <input
                id="word-ex-en"
                type="text"
                className="form-input"
                placeholder="He was persistent in pursuing his goals."
                value={exampleSentence}
                onChange={(e) => setExampleSentence(e.target.value)}
              />
            </div>

            <div className="form-group" style={{ marginTop: '10px' }}>
              <label className="form-label" htmlFor="word-ex-ja">例文訳 (日本語)</label>
              <input
                id="word-ex-ja"
                type="text"
                className="form-input"
                placeholder="彼は粘り強く目標を追い続けた。"
                value={exampleTranslation}
                onChange={(e) => setExampleTranslation(e.target.value)}
              />
            </div>

            <div className="form-actions">
              <button type="submit" className="nav-btn nav-btn-primary">
                <Plus size={16} />
                <span>単語カードを追加</span>
              </button>
            </div>
          </form>

          {/* 既存カードリスト */}
          <div className="word-table">
            <label className="form-label">登録済み単語一覧</label>
            {cards.map((c: WordCard) => (
              <div key={c.id} className="table-row">
                <div>
                  <strong style={{ fontSize: '0.95rem', color: '#0f172a' }}>{c.english}</strong>
                  <span style={{ fontSize: '0.75rem', color: '#64748b', marginLeft: '8px' }}>
                    [{c.category}]
                  </span>
                  <div style={{ fontSize: '0.82rem', color: '#475569', marginTop: '2px' }}>
                    {c.japanese}
                  </div>
                </div>
                <button
                  type="button"
                  className="delete-btn"
                  onClick={() => onDeleteCard?.(c.id)}
                  title="削除"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default WordListModal;

import { useState, useEffect, useCallback, useMemo } from 'react';
import { ChevronLeft, ChevronRight, Shuffle, RotateCcw, ListFilter } from 'lucide-react';
import { WordCard, FilterCategory } from './types';
import { defaultCards } from './data/words';
import CardView from './components/CardView';
import WordListModal from './components/WordListModal';
import './index.css';

const categories: FilterCategory[] = ['すべて', '日常', 'ビジネス', 'TOEIC', '旅行'];

const App = () => {
  const [cards, setCards] = useState<WordCard[]>(() => {
    const saved = localStorage.getItem('flashcards_data');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch {
        return defaultCards;
      }
    }
    return defaultCards;
  });

  const [selectedCategory, setSelectedCategory] = useState<FilterCategory>('すべて');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);

  // ローカルストレージ自動保存
  useEffect(() => {
    localStorage.setItem('flashcards_data', JSON.stringify(cards));
  }, [cards]);

  // フィルタリングされた単語一覧
  const filteredCards = useMemo(() => {
    if (selectedCategory === 'すべて') return cards;
    return cards.filter((c) => c.category === selectedCategory);
  }, [cards, selectedCategory]);

  // カテゴリ変更時にインデックス初期化
  const handleCategorySelect = (category: FilterCategory) => {
    setSelectedCategory(category);
    setCurrentIndex(0);
    setIsFlipped(false);
  };

  // 現在のカード
  const currentCard = filteredCards[currentIndex] || filteredCards[0];

  // 次のカードへ
  const handleNext = useCallback(() => {
    if (filteredCards.length <= 1) return;
    setIsFlipped(false);
    setCurrentIndex((prev) => (prev + 1) % filteredCards.length);
  }, [filteredCards.length]);

  // 前のカードへ
  const handlePrev = useCallback(() => {
    if (filteredCards.length <= 1) return;
    setIsFlipped(false);
    setCurrentIndex((prev) => (prev - 1 + filteredCards.length) % filteredCards.length);
  }, [filteredCards.length]);

  // カードを裏返す
  const handleFlip = useCallback(() => {
    setIsFlipped((prev) => !prev);
  }, []);

  // 暗記済み切り替え
  const handleToggleMastered = useCallback((id: string) => {
    setCards((prev) =>
      prev.map((card) =>
        card.id === id ? { ...card, isMastered: !card.isMastered } : card
      )
    );
  }, []);

  // シャッフル
  const handleShuffle = () => {
    setIsFlipped(false);
    setCards((prev) => {
      const copy = [...prev];
      for (let i = copy.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [copy[i], copy[j]] = [copy[j], copy[i]];
      }
      return copy;
    });
    setCurrentIndex(0);
  };

  // 暗記ステータスのリセット
  const handleResetProgress = () => {
    setIsFlipped(false);
    setCards((prev) => prev.map((card) => ({ ...card, isMastered: false })));
  };

  // 新規単語追加
  const handleAddCard = (newCardData: Omit<WordCard, 'id' | 'isMastered'>) => {
    const newCard: WordCard = {
      ...newCardData,
      id: `word-${Date.now()}`,
      isMastered: false,
    };
    setCards((prev) => [newCard, ...prev]);
    setCurrentIndex(0);
    setIsFlipped(false);
  };

  // 単語削除
  const handleDeleteCard = (id: string) => {
    setCards((prev) => {
      const updated = prev.filter((c) => c.id !== id);
      if (updated.length === 0) {
        return defaultCards;
      }
      return updated;
    });
    setCurrentIndex(0);
    setIsFlipped(false);
  };

  // 音声読み上げ
  const handleSpeak = (text: string) => {
    if (!('speechSynthesis' in window)) return;
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'en-US';
    utterance.rate = 0.9;
    window.speechSynthesis.speak(utterance);
  };

  // キーボードショートカット (左右キーで移動、Spaceキーで裏返し)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (isModalOpen) return;
      if (['input', 'textarea', 'select'].includes((e.target as HTMLElement).tagName.toLowerCase())) {
        return;
      }

      if (e.code === 'Space') {
        e.preventDefault();
        handleFlip();
      } else if (e.code === 'ArrowRight') {
        e.preventDefault();
        handleNext();
      } else if (e.code === 'ArrowLeft') {
        e.preventDefault();
        handlePrev();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleFlip, handleNext, handlePrev, isModalOpen]);

  // 進捗状況の計算
  const masteredCount = cards.filter((c) => c.isMastered).length;
  const progressPercent = cards.length > 0 ? Math.round((masteredCount / cards.length) * 100) : 0;

  return (
    <div className="app-container">
      {/* ヘッダー */}
      <header className="app-header">
        <h1 className="header-title">FlipVocab 3D</h1>
        <p className="header-subtitle">くるっと裏返して覚える英単語カード</p>
      </header>

      {/* 進捗バー */}
      <section className="stats-bar">
        <div className="stats-text">
          <span>全体の暗記進捗</span>
          <span>
            {masteredCount} / {cards.length} 語 ({progressPercent}%)
          </span>
        </div>
        <div className="progress-track">
          <div className="progress-fill" style={{ width: `${progressPercent}%` }} />
        </div>
      </section>

      {/* カテゴリ選択チップ */}
      <nav className="filter-chips">
        {categories.map((cat) => (
          <button
            key={cat}
            type="button"
            className={`chip-btn ${selectedCategory === cat ? 'chip-btn-active' : ''}`}
            onClick={() => handleCategorySelect(cat)}
          >
            {cat}
          </button>
        ))}
      </nav>

      {/* 単語カード本体 */}
      {currentCard ? (
        <CardView
          card={currentCard}
          isFlipped={isFlipped}
          onFlip={handleFlip}
          onToggleMastered={handleToggleMastered}
          onSpeak={handleSpeak}
        />
      ) : (
        <div style={{ textAlign: 'center', padding: '40px', color: '#cbd5e1' }}>
          該当する単語カードがありません
        </div>
      )}

      {/* ナビゲーション操作バー */}
      <div className="controls-row">
        <button
          type="button"
          className="nav-btn"
          onClick={handlePrev}
          disabled={filteredCards.length <= 1}
        >
          <ChevronLeft size={18} />
          <span>前へ</span>
        </button>

        <span style={{ fontSize: '0.88rem', fontWeight: 700, color: '#e2e8f0' }}>
          {filteredCards.length > 0 ? `${currentIndex + 1} / ${filteredCards.length}` : '0 / 0'}
        </span>

        <button
          type="button"
          className="nav-btn nav-btn-primary"
          onClick={handleNext}
          disabled={filteredCards.length <= 1}
        >
          <span>次へ</span>
          <ChevronRight size={18} />
        </button>
      </div>

      {/* サブアクション一覧 */}
      <div className="action-bar">
        <button type="button" className="sub-btn" onClick={handleShuffle}>
          <Shuffle size={14} />
          <span>シャッフル</span>
        </button>
        <button type="button" className="sub-btn" onClick={() => setIsModalOpen(true)}>
          <ListFilter size={14} />
          <span>単語管理・追加</span>
        </button>
        <button type="button" className="sub-btn" onClick={handleResetProgress}>
          <RotateCcw size={14} />
          <span>進捗リセット</span>
        </button>
      </div>

      {/* 単語リスト・追加モーダル */}
      <WordListModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        cards={cards}
        onAddCard={handleAddCard}
        onDeleteCard={handleDeleteCard}
      />
    </div>
  );
};

export default App;
